/**
 * CyberChef bridge daemon for Chimera.
 *
 * Loads the CyberChef node API and exposes it over a JSON-RPC style
 * protocol on stdio. One JSON object per line in both directions.
 *
 * Methods:
 *   ping                         -> {ok: true}
 *   list_operations              -> [{name, description, module, inputType,
 *                                     outputType, flowControl, args}]
 *   get_operation {name}         -> single operation metadata
 *   run_operation {name, args?, inputB64}
 *                                -> {outputB64, outputText, outputType}
 *   run_recipe {recipe, inputB64}
 *     recipe: [{op, args?}, ...] -> {outputB64, outputText, outputType}
 *
 * All binary payloads travel as base64 to keep the protocol text-safe.
 */

import { createRequire } from "module";
import { fileURLToPath } from "url";
import path from "path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Import the CyberChef node API (ESM).
const cyberchef = await import(path.join(__dirname, "../cyberchef/src/node/index.mjs"));
const chef = cyberchef.default;
// Array of wrapped operations (each has .opName and .args).
const wrappedOperations = cyberchef.operations;

// Full operation metadata (name -> config) generated by the CyberChef build.
const require = createRequire(import.meta.url);
const operationConfig = require("../cyberchef/src/core/config/OperationConfig.json");

const sanitise = (str) => String(str).replace(/[/\s.-]/g, "").toLowerCase();

/** Find a wrapped operation by name. */
function findOperation(name) {
    const target = sanitise(name);
    const op = wrappedOperations.find((candidate) => sanitise(candidate.opName) === target);
    if (!op) {
        throw new Error(`Operation not found: '${name}'. Use list_operations to see available operations.`);
    }
    return op;
}

/** Serialise a NodeDish result to {outputB64, outputText, outputType}. */
function serialiseDish(dish, outputType) {
    const result = { outputType: outputType || "string" };
    try {
        const text = dish.toString();
        result.outputText = text;
        result.outputB64 = Buffer.from(text, "utf8").toString("base64");
    } catch (e) {
        result.outputText = "";
        result.outputB64 = "";
    }
    try {
        const bytes = Array.from(dish.get(0)); // Dish.BYTE_ARRAY = 0
        result.outputBytesB64 = Buffer.from(bytes).toString("base64");
    } catch (e) {
        // Structured or string-only output; bytes unavailable.
    }
    return result;
}

/** Run a single operation. */
async function runOperation({ name, args = null, inputB64 = null }) {
    const op = findOperation(name);
    let input = null;
    if (inputB64 !== null && inputB64 !== undefined) {
        input = Buffer.from(inputB64, "base64");
    }
    const dish = await op(input, args);
    return serialiseDish(dish, op.outputType);
}

/** Run a recipe (chain of operations). */
async function runRecipe({ recipe, inputB64 = null }) {
    if (!Array.isArray(recipe) || recipe.length === 0) {
        throw new Error("Recipe must be a non-empty array of {op, args} objects");
    }
    const config = recipe.map((step) => {
        if (typeof step === "string") {
            return step;
        }
        if (step && typeof step === "object" && step.op) {
            return { op: step.op, args: step.args || {} };
        }
        throw new Error(`Invalid recipe step: ${JSON.stringify(step)}`);
    });
    let input = null;
    if (inputB64 !== null && inputB64 !== undefined) {
        input = Buffer.from(inputB64, "base64");
    }
    const dish = chef.bake(input, config);
    // Best-effort output type: use the last step's operation output type.
    const lastOp = config[config.length - 1];
    let outputType = "string";
    try {
        const op = typeof lastOp === "string" ? findOperation(lastOp) : findOperation(lastOp.op);
        outputType = op.outputType;
    } catch (e) {
        // fall back to string
    }
    return serialiseDish(dish, outputType);
}

/** Serialise operation metadata for MCP tool schemas. */
function serialiseOperation(name) {
    const cfg = operationConfig[name];
    if (!cfg) return null;
    return {
        name: name,
        description: cfg.description || "",
        module: cfg.module || "",
        inputType: cfg.inputType || "",
        outputType: cfg.outputType || "",
        flowControl: !!cfg.flowControl,
        manualBake: !!cfg.manualBake,
        args: (cfg.args || []).map((a) => ({
            name: a.name,
            type: a.type,
            value: a.value,
            toggleValues: a.toggleValues || undefined,
        })),
    };
}

function listOperations() {
    return Object.keys(operationConfig)
        .map(serialiseOperation)
        .filter((o) => o !== null);
}

function getOperation({ name }) {
    const cfg = operationConfig[name];
    if (!cfg) {
        const key = Object.keys(operationConfig).find(
            (k) => sanitise(k) === sanitise(name)
        );
        if (!key) throw new Error(`Operation not found: '${name}'`);
        return serialiseOperation(key);
    }
    return serialiseOperation(name);
}

// ---- line-delimited JSON-RPC loop ----
const readline = (await import("readline")).createInterface({
    input: process.stdin,
    crlfDelay: Infinity,
});

readline.on("line", async (line) => {
    let msg;
    try {
        msg = JSON.parse(line);
    } catch (e) {
        process.stdout.write(JSON.stringify({ ok: false, error: "Invalid JSON request" }) + "\n");
        return;
    }

    const { id, method, params } = msg;
    try {
        let result;
        switch (method) {
            case "ping":
                result = { ok: true, version: "cyberchef-10.24.0" };
                break;
            case "list_operations":
                result = { operations: listOperations() };
                break;
            case "get_operation":
                result = getOperation(params);
                break;
            case "run_operation":
                result = await runOperation(params);
                break;
            case "run_recipe":
                result = await runRecipe(params);
                break;
            default:
                throw new Error(`Unknown method: ${method}`);
        }
        process.stdout.write(JSON.stringify({ id, ok: true, result }) + "\n");
    } catch (e) {
        process.stdout.write(JSON.stringify({ id, ok: false, error: String(e.message || e) }) + "\n");
    }
});
